def matmul(A,B):
    return [[sum(A[i][k]*B[k][j] for k in range(len(B)))
             for j in range(len(B[0]))] for i in range(len(A))]

def transpose(A):
    return [list(x) for x in zip(*A)]

def add(A,B):
    return [[A[i][j]+B[i][j] for j in range(len(A[0]))] for i in range(len(A))]

def basis(n, skew):
    out=[]
    if not skew:
        for i in range(n):
            X=[[0]*n for _ in range(n)]; X[i][i]=1; out.append(X)
        for i in range(n):
            for j in range(i+1,n):
                X=[[0]*n for _ in range(n)]
                X[i][j]=X[j][i]=1; out.append(X)
        D=[1]*n+[2]*(n*(n-1)//2)
    else:
        for i in range(n):
            for j in range(i+1,n):
                X=[[0]*n for _ in range(n)]
                X[i][j]=1; X[j][i]=-1; out.append(X)
        D=[2]*(n*(n-1)//2)
    return out,D

def coords(Y, skew):
    n=len(Y)
    if not skew:
        return [Y[i][i] for i in range(n)] + [Y[i][j] for i in range(n) for j in range(i+1,n)]
    return [Y[i][j] for i in range(n) for j in range(i+1,n)]

def coord_matrix(A, skew):
    n=len(A); Bs,D=basis(n,skew); AT=transpose(A)
    cols=[]
    for X in Bs:
        Y=add(matmul(A,X),matmul(X,AT))
        cols.append(coords(Y,skew))
    m=len(cols)
    return [[cols[j][i] for j in range(m)] for i in range(m)],D

def gram(B,D):
    m=len(B)
    return [[sum(B[k][i]*D[k]*B[k][j] for k in range(m)) for j in range(m)] for i in range(m)]

def ldl_positive(M):
    n=len(M)
    L=[[Fraction(0) for _ in range(n)] for __ in range(n)]
    D=[Fraction(0) for _ in range(n)]
    for i in range(n):
        L[i][i]=Fraction(1)
        p=Fraction(M[i][i])
        for k in range(i):
            p -= L[i][k]*L[i][k]*D[k]
        if p <= 0:
            return False, D+[p]
        D[i]=p
        for j in range(i+1,n):
            z=Fraction(M[j][i])
            for k in range(i):
                z -= L[j][k]*L[i][k]*D[k]
            L[j][i]=z/D[i]
    return True,D

def delete_row_col(A,r,c):
    return [[A[i][j] for j in range(7) if j != c] for i in range(7) if i != r]

checked=0
min_lower_margin=None
min_pivot=None
for r1,c1,tau,v in CERTS:
    A=delete_row_col(A7,r1-1,c1-1)
    BS,DS=coord_matrix(A,False)
    BK,DK=coord_matrix(A,True)
    GS=gram(BS,DS); GK=gram(BK,DK)
    num=sum(v[i]*GS[i][j]*v[j] for i in range(len(v)) for j in range(len(v)))
    den=sum(DS[i]*v[i]*v[i] for i in range(len(v)))
    lower_margin=num-tau*den
    assert lower_margin>0, (r1,c1,"symmetric lower certificate failed")
    MK=[[tau*DK[i] if i==j else 0 for j in range(len(DK))] for i in range(len(DK))]
    MK=[[MK[i][j]-GK[i][j] for j in range(len(DK))] for i in range(len(DK))]
    ok,pivs=ldl_positive(MK)
    assert ok, (r1,c1,"skew upper certificate failed")
    mp=min(pivs)
    min_lower_margin=lower_margin if min_lower_margin is None else min(min_lower_margin,lower_margin)
    min_pivot=mp if min_pivot is None else min(min_pivot,mp)
    checked += 1

assert checked==49
print("checked_submatrices=49")
print("all_exact_strict_symmetric_gt_skew=True")
print("min_integer_lower_margin=",min_lower_margin)
print("min_ldl_pivot=",min_pivot)
print("ALL_EXACT_CHECKS_PASS")
